SELECT COALESCE(SUM(total_tokens), 0) AS tokenTotal,
       COALESCE(SUM(cost_amount), 0) AS costAmount,
       COUNT(DISTINCT currency) AS currencyCount,
       MIN(currency) AS currency
FROM token_usage
WHERE tenant_id = #{tenantId}
  AND created_at >= #{periodStart}
  AND created_at < #{periodEnd}

SELECT id, run_id, tenant_id, user_id, session_id, model,
       input_tokens, output_tokens, total_tokens, cost_amount, currency
FROM token_usage
WHERE user_id = #{userId}
  AND tenant_id = #{tenantId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}

SELECT id, run_id, tenant_id, session_id, model,
       input_tokens, output_tokens, total_tokens, cost_amount, currency, created_at
FROM token_usage
WHERE id = #{id}
  AND user_id = #{userId}
  AND tenant_id = #{tenantId}
LIMIT 1
